static char __builtin_stdbool_h[334] = "/* stdbool.h - Boolean type support */\n\n#ifndef __STDBOOL_H\n#define __STDBOOL_H\n\n#if __STDC_VERSION__ < 202311L\n/* Before C23, bool/true/false are macros aliasing _Bool/1/0 */\n#define bool _Bool\n#define true 1\n#define false 0\n#endif\n\n/* Standard conformance macro */\n#define __bool_true_false_are_defined 1\n\n#endif /* __STDBOOL_H */\n";
static char __builtin_stdckdint_h[411] = "/* stdckdint.h - C23 checked integer arithmetic for CCCC C compiler */\n\n#ifndef __STDCKDINT_H\n#define __STDCKDINT_H\n\n#define __STDC_VERSION_STDCKDINT_H__ 202311L\n\n#define ckd_add(result, a, b) __builtin_add_overflow((a), (b), (result))\n#define ckd_sub(result, a, b) __builtin_sub_overflow((a), (b), (result))\n#define ckd_mul(result, a, b) __builtin_mul_overflow((a), (b), (result))\n\n#endif /* __STDCKDINT_H */\n";
static char __builtin_stddef_h[460] = "/* stddef.h - standard definitions for CCCC C compiler */\n\n#ifndef __STDDEF_H\n#define __STDDEF_H\n\ntypedef long ptrdiff_t;\ntypedef long size_t;\ntypedef int wchar_t;\n\n#if __STDC_VERSION__ >= 202311L\ntypedef typeof(nullptr) nullptr_t;\n#define unreachable() __builtin_unreachable()\n#endif\n\n#define NULL ((void*)0)\n\n/* offsetof macro - works with standard layout structs */\n#define offsetof(type, member) ((size_t) &(((type *)0)->member))\n\n#endif /* __STDDEF_H */\n";
static char __builtin_stdint_h[1134] = "/* stdint.h - fixed-width integer types for CCCC C compiler */\n\n#ifndef __STDINT_H\n#define __STDINT_H\n\n/* On this VM, long is 8 bytes */\ntypedef signed char int8_t;\ntypedef short int16_t;\ntypedef int int32_t;\ntypedef long int64_t;\n\ntypedef unsigned char uint8_t;\ntypedef unsigned short uint16_t;\ntypedef unsigned int uint32_t;\ntypedef unsigned long uint64_t;\n\ntypedef long intptr_t;\ntypedef unsigned long uintptr_t;\n\ntypedef long intmax_t;\ntypedef unsigned long uintmax_t;\n\n#define INTPTR_MIN  (-9223372036854775807L-1)\n#define INTPTR_MAX  9223372036854775807L\n#define UINTPTR_MAX 18446744073709551615UL\n\n#define INTMAX_MIN  (-9223372036854775807L-1)\n#define INTMAX_MAX  9223372036854775807L\n#define UINTMAX_MAX 18446744073709551615UL\n\n#define INT8_MIN   (-128)\n#define INT8_MAX   127\n#define INT16_MIN  (-32768)\n#define INT16_MAX  32767\n#define INT32_MIN  (-2147483648)\n#define INT32_MAX  2147483647\n#define INT64_MIN  (-9223372036854775807L-1)\n#define INT64_MAX  9223372036854775807L\n\n#define UINT8_MAX  255\n#define UINT16_MAX 65535\n#define UINT32_MAX 4294967295U\n#define UINT64_MAX 18446744073709551615UL\n\n#endif /* __STDINT_H */\n";
static char __builtin_stdio_h[3950] = "/*\n * stdio.h - Standard I/O functions for CCCC VM\n */\n\n#ifndef __STDIO_H\n#define __STDIO_H\n\n#include \"stdarg.h\"\n#include \"stddef.h\"\n\n// FILE type (opaque pointer to host FILE)\ntypedef void FILE;\n\n// Standard streams (accessed via getter functions)\nextern FILE* __cccc_stdin(void);\nextern FILE* __cccc_stdout(void);\nextern FILE* __cccc_stderr(void);\n#define stdin __cccc_stdin()\n#define stdout __cccc_stdout()\n#define stderr __cccc_stderr()\n\n/* Types and macros from the C standard */\ntypedef long fpos_t;\n\n/* Buffering and limits */\n#ifndef BUFSIZ\n#define BUFSIZ 8192\n#endif\n\n#ifndef EOF\n#define EOF (-1)\n#endif\n\n#ifndef FILENAME_MAX\n#define FILENAME_MAX 4096\n#endif\n\n#ifndef FOPEN_MAX\n#define FOPEN_MAX 20\n#endif\n\n#ifndef L_tmpnam\n#define L_tmpnam 20\n#endif\n\n#ifndef TMP_MAX\n#define TMP_MAX 238328\n#endif\n\n/* Seek constants */\n#ifndef SEEK_SET\n#define SEEK_SET 0\n#define SEEK_CUR 1\n#define SEEK_END 2\n#endif\n\n/* setvbuf modes */\n#ifndef _IOFBF\n#define _IOFBF 0\n#define _IOLBF 1\n#define _IONBF 2\n#endif\n\n// ==================================================\n// Variadic function declarations \n// ==================================================\n// Supported via platform inline assembly\n\n// Printf family\nextern int printf(const char *fmt, ...)\n    __attribute__((format(printf, 1, 2)));\nextern int fprintf(FILE *stream, const char *fmt, ...)\n    __attribute__((format(printf, 2, 3)));\nextern int sprintf(char *str, const char *fmt, ...)\n    __attribute__((format(printf, 2, 3)));\nextern int snprintf(char *str, size_t size, const char *fmt, ...)\n    __attribute__((format(printf, 3, 4)));\n\n// Scanf family\nextern int scanf(const char *fmt, ...)\n    __attribute__((format(scanf, 1, 2)));\nextern int sscanf(const char *str, const char *fmt, ...)\n    __attribute__((format(scanf, 2, 3)));\nextern int fscanf(FILE *stream, const char *fmt, ...)\n    __attribute__((format(scanf, 2, 3)));\n\n// V* variants (take va_list) - Note: va_list manipulation not fully supported in VM\n// These are provided for completeness but may not work as expected\nextern int vprintf(char *fmt, va_list ap);\nextern int vsprintf(char *str, char *fmt, va_list ap);\nextern int vsnprintf(char *str, long size, char *fmt, va_list ap);\nextern int vfprintf(FILE *stream, char *fmt, va_list ap);\nextern int vscanf(char *fmt, va_list ap);\nextern int vsscanf(char *str, char *fmt, va_list ap);\nextern int vfscanf(FILE *stream, char *fmt, va_list ap);\n\n// ==================================================\n// Common non-variadic stdio functions (both modes)\n// ==================================================\n\n\nextern int remove(const char* filename);\nextern int rename(const char* old, const char* new);\nextern FILE* tmpfile(void);\nextern char* tmpnam(char* s);\nextern int fclose(FILE* stream);\nextern int fflush(FILE* stream);\nextern FILE* fopen(const char* filename, const char* mode);\nextern FILE* freopen(const char* filename, const char* mode, FILE* stream);\nextern void setbuf(FILE* stream, char* buf);\nextern int setvbuf(FILE* stream, char* buf, int mode, size_t size);\nextern int fgetc(FILE* stream);\nextern char* fgets(char* s, int n, FILE* stream);\nextern int fputc(int c, FILE* stream);\nextern int fputs(const char* s, FILE* stream);\nextern int getc(FILE* stream);\nextern int getchar(void);\nextern int putc(int c, FILE* stream);\nextern int putchar(int c);\nextern int puts(const char* s);\nextern int ungetc(int c, FILE* stream);\nextern size_t fread(void* ptr, size_t size, size_t nmemb, FILE* stream);\nextern size_t fwrite(const void* ptr, size_t size, size_t nmemb, FILE* stream);\nextern int fgetpos(FILE* stream, fpos_t* pos);\nextern int fseek(FILE* stream, long int offset, int whence);\nextern int fsetpos(FILE* stream, const fpos_t* pos);\nextern long int ftell(FILE* stream);\nextern void rewind(FILE* stream);\nextern void clearerr(FILE* stream);\nextern int feof(FILE* stream);\nextern int ferror(FILE* stream);\nextern void perror(const char* s);\n\n#endif // __STDIO_H\n";
static char __builtin_stdlib_h[3038] = "// Standard library function declarations for FFI\n// This header provides declarations for C standard library functions\n// that are registered in the VM's FFI and can be called directly\n\n#ifndef __STDLIB_H\n#define __STDLIB_H \n\n#include \"stddef.h\"\n\n/* EXIT macros */\n#ifndef EXIT_SUCCESS\n#define EXIT_SUCCESS 0\n#endif\n#ifndef EXIT_FAILURE\n#define EXIT_FAILURE 1\n#endif\n\n// typedef unsigned int once_flag;\n// extern void call_once(once_flag* flag, void (*func)(void));\n\nextern double atof(const char* nptr);\nextern int atoi(const char* nptr);\nextern long int atol(const char* nptr);\nextern long long int atoll(const char* nptr);\n// extern int strfromd(char* s, size_t n, const char* format, double fp);\n// extern int strfromf(char* s, size_t n, const char* format, float fp);\n// extern int strfroml(char* s, size_t n, const char* format, long double fp);\nextern double strtod(const char* nptr, char** endptr);\nextern float strtof(const char* nptr, char** endptr);\nextern long double strtold(const char* nptr, char** endptr);\nextern long int strtol(const char* nptr, char** endptr, int base);\nextern long long int strtoll(const char* nptr, char** endptr, int base);\nextern unsigned long int strtoul(const char* nptr, char** endptr, int base);\nextern unsigned long long int strtoull(const char* nptr, char** endptr, int base);\n\nextern int rand(void);\nextern void srand(unsigned int seed);\nextern void* aligned_alloc(size_t alignment, size_t size);\nextern void* calloc(size_t nmemb, size_t size);\nextern void free(void* ptr);\nextern void free_sized(void* ptr, size_t size);\nextern void free_aligned_sized(void* ptr, size_t alignment, size_t size);\nextern void* malloc(size_t size);\nextern void* realloc(void* ptr, size_t size);\nextern void abort(void);\nextern int atexit(void (*func)(void));\nextern int at_quick_exit(void (*func)(void));\nextern void exit(int status);\nextern void _Exit(int status);\nextern char* getenv(const char* name);\nextern void quick_exit(int status);\nextern int system(const char* string);\nextern int posix_memalign(void** memptr, size_t alignment, size_t size);\nextern void* bsearch(const void* key, void* base, size_t nmemb, size_t size, int (*compar)(const void* , const void* ));\nextern void qsort(void* base, size_t nmemb, size_t size, int (*compar)(const void* , const void* ));\nextern int abs(int j);\nextern long int labs(long int j);\nextern long long int llabs(long long int j);\n\ntypedef struct { int quot; int rem; } div_t;\ntypedef struct { long quot; long rem; } ldiv_t;\ntypedef struct { long long quot; long long rem; } lldiv_t;\n\nextern div_t div(int numer, int denom);\nextern ldiv_t ldiv(long int numer, long int denom);\nextern lldiv_t lldiv(long long int numer, long long int denom);\n\nextern int mblen(const char* s, size_t n);\nextern int mbtowc(wchar_t* pwc, const char* s, size_t n);\nextern int wctomb(char* s, wchar_t wc);\n\nextern size_t mbstowcs(wchar_t* pwcs, const char* s, size_t n);\nextern size_t wcstombs(char* s, const wchar_t* pwcs, size_t n);\nextern size_t memalignment(const void* p);\n\n#endif\n";
static char __builtin_stdnoreturn_h[85] = "#ifndef __STDNORETURN_H\n#define __STDNORETURN_H\n\n#define noreturn _Noreturn\n\n#endif\n";
static char __builtin_string_h[3000] = "/* string.h - string manipulation functions for CCCC C compiler */\n\n#ifndef __STRING_H\n#define __STRING_H\n\nextern void *memcpy(void *dest, const void *src, long n);\nextern void *memmove(void *dest, const void *src, long n);\nextern void *memset(void *s, int c, long n);\nextern int memcmp(const void *s1, const void *s2, long n);\nextern void *memchr(const void *s, int c, long n);\n\nextern long strlen(const char *s);\nextern char *strcpy(char *dest, const char *src);\nextern char *strncpy(char *dest, const char *src, long n);\nextern char *strcat(char *dest, const char *src);\nextern char *strncat(char *dest, const char *src, long n);\nextern int strcmp(const char *s1, const char *s2);\nextern int strncmp(const char *s1, const char *s2, long n);\n\n/* C23 const-correct search functions: return type matches const-ness of input.\n * Macros use the parenthesized (funcname) form to call the actual function and\n * avoid recursive macro expansion. Declarations use the same form so the macro\n * is never applied to the declaration itself. */\n\n#define strchr(s, c) \\\n    _Generic((s), \\\n        const char *: (const char *)(strchr)((s), (c)), \\\n        char *:                     (strchr)((s), (c)))\nextern char *(strchr)(const char *s, int c);\n\n#define strrchr(s, c) \\\n    _Generic((s), \\\n        const char *: (const char *)(strrchr)((s), (c)), \\\n        char *:                     (strrchr)((s), (c)))\nextern char *(strrchr)(const char *s, int c);\n\n#define strstr(haystack, needle) \\\n    _Generic((haystack), \\\n        const char *: (const char *)(strstr)((haystack), (needle)), \\\n        char *:                     (strstr)((haystack), (needle)))\nextern char *(strstr)(const char *haystack, const char *needle);\n\n#define strpbrk(s, accept) \\\n    _Generic((s), \\\n        const char *: (const char *)(strpbrk)((s), (accept)), \\\n        char *:                     (strpbrk)((s), (accept)))\nextern char *(strpbrk)(const char *s, const char *accept);\n\nextern long strxfrm(char *dest, const char *src, long n);\nextern char* strerror(int errnum);\n\n// extern char* strcpy_s(char *dest, long destsz, const char *src);\n// extern char* strncpy_s(char *dest, long destsz, const char *src, long n);\n// extern char* strcat_s(char *dest, long destsz, const char *src);\n// extern char* strncat_s(char *dest, long destsz, const char *src, long n);\nextern char* strdup(const char *s);\nextern char* strndup(const char *s, long n);\n// extern long strnlen_s(const char *s, long maxsize);\n// extern char* strtok_s(char *str, const char *delim, char **context);\nextern void* memset_explicit(void *s, int c, long n);\n// extern int memset_s(void *s, long smax, int c, long n);\n// extern void* memcpy_s(void *dest, long destsz, const void *src, long n);\n// extern void* memmove_s(void *dest, long destsz, const void *src, long n);\nextern void* memccpy(void *dest, const void *src, int c, long n);\n// extern int strerror_s(char *buf, long bufsz, int errnum);\n// extern long strerrorlen_s(int errnum);\n\n#endif /* __STRING_H */\n";
static char __builtin_strings_h[597] = "/* strings.h - POSIX string functions supplement for CCCC */\n\n#ifndef __STRINGS_H\n#define __STRINGS_H\n\n#ifdef _WIN32\n#error \"<strings.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"stddef.h\"\n\nextern int strcasecmp(const char *s1, const char *s2);\nextern int strncasecmp(const char *s1, const char *s2, size_t n);\nextern void bzero(void *s, size_t n);\nextern void bcopy(const void *src, void *dst, size_t n);\nextern int bcmp(const void *s1, const void *s2, size_t n);\nextern char *index(const char *s, int c);\nextern char *rindex(const char *s, int c);\n\n#endif /* __STRINGS_H */\n";
static char __builtin_sys_cdefs_h[761] = "/*\n * CCCC wrapper for sys/cdefs.h\n * \n * This stub includes Availability.h first (to set up CCCC compatibility macros)\n * then includes the real sys/cdefs.h from the system include path.\n * \n * The order matters because sys/cdefs.h uses __GNUC__ and __has_attribute\n * to define macros that CCCC cannot parse (like __attribute__((__always_inline__))).\n * By including Availability.h first, we ensure __has_attribute returns 0\n * and __attribute__ is stripped.\n */\n\n#ifndef _CCCC_SYS_CDEFS_H_\n#define _CCCC_SYS_CDEFS_H_\n\n/* Include CCCC's Availability.h stub first to set up compatibility macros */\n#include <Availability.h>\n\n/* Now include the real sys/cdefs.h - but we need to use include_next */\n#include_next <sys/cdefs.h>\n\n#endif /* _CCCC_SYS_CDEFS_H_ */\n";
static char __builtin_sys_mman_h[1182] = "/* sys/mman.h - memory management declarations for CCCC */\n\n#ifndef __SYS_MMAN_H\n#define __SYS_MMAN_H\n\n#ifdef _WIN32\n#error \"<sys/mman.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"unistd.h\"\n\n#define PROT_NONE  0x00\n#define PROT_READ  0x01\n#define PROT_WRITE 0x02\n#define PROT_EXEC  0x04\n\n#ifdef __APPLE__\n#define MAP_SHARED    0x0001\n#define MAP_PRIVATE   0x0002\n#define MAP_FIXED     0x0010\n#define MAP_ANON      0x1000\n#define MAP_ANONYMOUS MAP_ANON\n#else\n#define MAP_SHARED    0x01\n#define MAP_PRIVATE   0x02\n#define MAP_FIXED     0x10\n#define MAP_ANONYMOUS 0x20\n#define MAP_ANON      MAP_ANONYMOUS\n#endif\n\n#define MS_ASYNC      0x0001\n#define MS_SYNC       0x0002\n#define MS_INVALIDATE 0x0004\n\n#define MADV_NORMAL     0\n#define MADV_RANDOM     1\n#define MADV_SEQUENTIAL 2\n#define MADV_WILLNEED   3\n#define MADV_DONTNEED   4\n\nextern void *mmap(void *addr, size_t length, int prot, int flags, int fd, off_t offset);\nextern int munmap(void *addr, size_t length);\nextern int mprotect(void *addr, size_t len, int prot);\nextern int msync(void *addr, size_t len, int flags);\nextern int posix_madvise(void *addr, size_t len, int advice);\n\n#endif /* __SYS_MMAN_H */\n";
static char __builtin_sys_socket_h[1311] = "/* sys/socket.h - socket declarations for CCCC */\n\n#ifndef __SYS_SOCKET_H\n#define __SYS_SOCKET_H\n\n#ifdef _WIN32\n#error \"<sys/socket.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"sys/types.h\"\n\n#ifdef __APPLE__\nstruct sockaddr {\n    unsigned char sa_len;\n    sa_family_t sa_family;\n    char sa_data[14];\n};\n#else\nstruct sockaddr {\n    sa_family_t sa_family;\n    char sa_data[14];\n};\n#endif\n\n#define SOCK_STREAM 1\n#define SOCK_DGRAM  2\n#define SOCK_RAW    3\n\n#ifdef __APPLE__\n#define SOL_SOCKET   0xffff\n#define SO_REUSEADDR 0x0004\n#else\n#define SOL_SOCKET   1\n#define SO_REUSEADDR 2\n#endif\n\n#define SHUT_RD   0\n#define SHUT_WR   1\n#define SHUT_RDWR 2\n\nextern int socket(int domain, int type, int protocol);\nextern int bind(int socket, const struct sockaddr *address, socklen_t address_len);\nextern int listen(int socket, int backlog);\nextern int accept(int socket, struct sockaddr *address, socklen_t *address_len);\nextern int connect(int socket, const struct sockaddr *address, socklen_t address_len);\nextern int setsockopt(int socket, int level, int option_name,\n                      const void *option_value, socklen_t option_len);\nextern int getsockname(int socket, struct sockaddr *address, socklen_t *address_len);\nextern int shutdown(int socket, int how);\n\n#endif /* __SYS_SOCKET_H */\n";
static char __builtin_sys_stat_h[3085] = "/* sys/stat.h - file status for CCCC */\n\n#ifndef __SYS_STAT_H\n#define __SYS_STAT_H\n\n#ifdef _WIN32\n#error \"<sys/stat.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"sys/types.h\"\n\n/* Pull in struct timespec and time_t */\n#include \"../time.h\"\n\n#ifdef __APPLE__\n\nstruct stat {\n    dev_t     st_dev;\n    mode_t    st_mode;\n    nlink_t   st_nlink;\n    ino_t     st_ino;\n    uid_t     st_uid;\n    gid_t     st_gid;\n    dev_t     st_rdev;\n    struct timespec st_atimespec;\n    struct timespec st_mtimespec;\n    struct timespec st_ctimespec;\n    struct timespec st_birthtimespec;\n    off_t     st_size;\n    blkcnt_t  st_blocks;\n    blksize_t st_blksize;\n    unsigned int st_flags;\n    unsigned int st_gen;\n    int       st_lspare;\n    long long st_qspare[2];\n};\n\n#elif defined(__x86_64__)\n/* Linux x86_64 glibc layout (sizeof==144, offsetof(st_size)==48, offsetof(st_mtim)==88) */\n\nstruct stat {\n    dev_t     st_dev;\n    ino_t     st_ino;\n    nlink_t   st_nlink;   /* nlink precedes mode on x86_64 */\n    mode_t    st_mode;\n    uid_t     st_uid;\n    gid_t     st_gid;\n    int       __pad0;\n    dev_t     st_rdev;\n    off_t     st_size;\n    blksize_t st_blksize; /* long (8 bytes) on x86_64 */\n    blkcnt_t  st_blocks;\n    struct timespec st_atim;\n    struct timespec st_mtim;\n    struct timespec st_ctim;\n    long      __glibc_reserved[3];\n};\n\n_Static_assert(sizeof(struct stat) == 144, \"x86_64 struct stat layout mismatch\");\n\n#else\n/* Linux aarch64 / generic POSIX */\n\nstruct stat {\n    dev_t st_dev;\n    ino_t st_ino;\n    mode_t st_mode;\n    nlink_t st_nlink;\n    uid_t st_uid;\n    gid_t st_gid;\n    dev_t st_rdev;\n    dev_t __pad1;\n    off_t st_size;\n    blksize_t st_blksize;\n    int __pad2;\n    blkcnt_t st_blocks;\n    struct timespec st_atim;\n    struct timespec st_mtim;\n    struct timespec st_ctim;\n    int __glibc_reserved[2];\n};\n\n#endif\n\n#define S_IFMT   0xF000\n#define S_IFIFO  0x1000\n#define S_IFCHR  0x2000\n#define S_IFDIR  0x4000\n#define S_IFBLK  0x6000\n#define S_IFREG  0x8000\n#define S_IFLNK  0xA000\n#define S_IFSOCK 0xC000\n\n#define S_ISFIFO(m) (((m) & S_IFMT) == S_IFIFO)\n#define S_ISCHR(m)  (((m) & S_IFMT) == S_IFCHR)\n#define S_ISDIR(m)  (((m) & S_IFMT) == S_IFDIR)\n#define S_ISBLK(m)  (((m) & S_IFMT) == S_IFBLK)\n#define S_ISREG(m)  (((m) & S_IFMT) == S_IFREG)\n#define S_ISLNK(m)  (((m) & S_IFMT) == S_IFLNK)\n#define S_ISSOCK(m) (((m) & S_IFMT) == S_IFSOCK)\n\n#define S_IRWXU  0700\n#define S_IRUSR  0400\n#define S_IWUSR  0200\n#define S_IXUSR  0100\n#define S_IRWXG  0070\n#define S_IRGRP  0040\n#define S_IWGRP  0020\n#define S_IXGRP  0010\n#define S_IRWXO  0007\n#define S_IROTH  0004\n#define S_IWOTH  0002\n#define S_IXOTH  0001\n\n#define S_ISUID  04000\n#define S_ISGID  02000\n#define S_ISVTX  01000\n\nextern int stat(const char *path, struct stat *buf);\nextern int fstat(int fd, struct stat *buf);\nextern int lstat(const char *path, struct stat *buf);\nextern int chmod(const char *path, mode_t mode);\nextern int mkdir(const char *path, mode_t mode);\nextern int mkfifo(const char *path, mode_t mode);\nextern mode_t umask(mode_t cmask);\n\n#endif /* __SYS_STAT_H */\n";
static char __builtin_sys_time_h[996] = "/* sys/time.h - time types for CCCC */\n\n#ifndef __SYS_TIME_H\n#define __SYS_TIME_H\n\n#ifdef _WIN32\n#error \"<sys/time.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"time.h\"\n\nstruct timeval {\n    long tv_sec;\n    long tv_usec;\n};\n\nstruct timezone {\n    int tz_minuteswest;\n    int tz_dsttime;\n};\n\nextern int gettimeofday(struct timeval *tv, struct timezone *tz);\nextern int settimeofday(const struct timeval *tv, const struct timezone *tz);\n\n#define timeradd(a, b, res) do { \\\n    (res)->tv_sec = (a)->tv_sec + (b)->tv_sec; \\\n    (res)->tv_usec = (a)->tv_usec + (b)->tv_usec; \\\n    if ((res)->tv_usec >= 1000000) { \\\n        (res)->tv_sec++; \\\n        (res)->tv_usec -= 1000000; \\\n    } \\\n} while (0)\n\n#define timersub(a, b, res) do { \\\n    (res)->tv_sec = (a)->tv_sec - (b)->tv_sec; \\\n    (res)->tv_usec = (a)->tv_usec - (b)->tv_usec; \\\n    if ((res)->tv_usec < 0) { \\\n        (res)->tv_sec--; \\\n        (res)->tv_usec += 1000000; \\\n    } \\\n} while (0)\n\n#endif /* __SYS_TIME_H */\n";
static char __builtin_sys_types_h[1326] = "/* sys/types.h - basic system types for CCCC */\n\n#ifndef __SYS_TYPES_H\n#define __SYS_TYPES_H\n\n#ifdef _WIN32\n#error \"<sys/types.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#ifdef __APPLE__\ntypedef int               dev_t;\ntypedef unsigned long long ino_t;\ntypedef unsigned short    mode_t;\ntypedef unsigned short    nlink_t;\ntypedef unsigned int      uid_t;\ntypedef unsigned int      gid_t;\ntypedef long long         off_t;\ntypedef int               pid_t;\ntypedef int               blksize_t;\ntypedef long long         blkcnt_t;\ntypedef unsigned int      useconds_t;\ntypedef unsigned char     sa_family_t;\ntypedef unsigned int      socklen_t;\n#else\n/* Linux / generic POSIX */\ntypedef unsigned long     dev_t;\ntypedef unsigned long     ino_t;\ntypedef unsigned int      mode_t;\n#if defined(__aarch64__)\ntypedef unsigned int      nlink_t;\n#else\ntypedef unsigned long     nlink_t;\n#endif\ntypedef unsigned int      uid_t;\ntypedef unsigned int      gid_t;\ntypedef long              off_t;\ntypedef int               pid_t;\n#if defined(__aarch64__)\ntypedef int               blksize_t;\n#else\ntypedef long              blksize_t;\n#endif\ntypedef long              blkcnt_t;\ntypedef unsigned int      useconds_t;\ntypedef unsigned short    sa_family_t;\ntypedef unsigned int      socklen_t;\n#endif\n\n#endif /* __SYS_TYPES_H */\n";
static char __builtin_sys_wait_h[755] = "/* sys/wait.h - process wait declarations for CCCC */\n\n#ifndef __SYS_WAIT_H\n#define __SYS_WAIT_H\n\n#ifdef _WIN32\n#error \"<sys/wait.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"unistd.h\"\n\n#define WNOHANG    1\n#define WUNTRACED  2\n\n#define WIFEXITED(status)   (((status) & 0x7f) == 0)\n#define WEXITSTATUS(status) (((status) >> 8) & 0xff)\n#define WIFSIGNALED(status) ((((status) & 0x7f) > 0) && (((status) & 0x7f) < 0x7f))\n#define WTERMSIG(status)    ((status) & 0x7f)\n#define WIFSTOPPED(status)  (((status) & 0xff) == 0x7f)\n#define WSTOPSIG(status)    WEXITSTATUS(status)\n#define WCOREDUMP(status)   ((status) & 0x80)\n\nextern pid_t wait(int *status);\nextern pid_t waitpid(pid_t pid, int *status, int options);\n\n#endif /* __SYS_WAIT_H */\n";
static char __builtin_termios_h[1507] = "/* termios.h - terminal I/O declarations for CCCC */\n\n#ifndef __TERMIOS_H\n#define __TERMIOS_H\n\n#ifdef _WIN32\n#error \"<termios.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#ifdef __APPLE__\ntypedef unsigned long tcflag_t;\ntypedef unsigned char cc_t;\ntypedef unsigned long speed_t;\n#define NCCS 20\nstruct termios {\n    tcflag_t c_iflag;\n    tcflag_t c_oflag;\n    tcflag_t c_cflag;\n    tcflag_t c_lflag;\n    cc_t c_cc[NCCS];\n    speed_t c_ispeed;\n    speed_t c_ospeed;\n};\n#else\ntypedef unsigned int tcflag_t;\ntypedef unsigned char cc_t;\ntypedef unsigned int speed_t;\n#define NCCS 32\nstruct termios {\n    tcflag_t c_iflag;\n    tcflag_t c_oflag;\n    tcflag_t c_cflag;\n    tcflag_t c_lflag;\n    cc_t c_line;\n    cc_t c_cc[NCCS];\n    speed_t c_ispeed;\n    speed_t c_ospeed;\n};\n#endif\n\n#define TCSANOW   0\n#define TCSADRAIN 1\n#define TCSAFLUSH 2\n\n#define VEOF   0\n#define VEOL   1\n#define VERASE 3\n#define VINTR  8\n#define VMIN   16\n#define VTIME  17\n\n#define BRKINT  0x00000002\n#define ICRNL   0x00000100\n#define IXON    0x00000200\n#define OPOST   0x00000001\n#define CS8     0x00000300\n#define CREAD   0x00000800\n#define ECHO    0x00000008\n#define ICANON  0x00000100\n#define ISIG    0x00000080\n\n#define B0       0\n#define B9600    9600\n#define B19200   19200\n#define B38400   38400\n#define B115200  115200\n\nextern int tcgetattr(int fildes, struct termios *termios_p);\nextern int tcsetattr(int fildes, int optional_actions,\n                     const struct termios *termios_p);\n\n#endif /* __TERMIOS_H */\n";
static char __builtin_testing_h[29979] = "/*!\n * @file testing.h\n * @brief CCCC Test Framework \342\200\224 assertion API injected in --testing mode.\n *\n * This header provides macros and underlying FFI-callable builtins for writing\n * self-verifying test programs.  It is automatically injected when CCCC is\n * invoked with the @c --testing flag and should not be included directly.\n *\n * A test passes if it exits with code 42.\n *\n * ## Usage\n *\n * @code\n * int main(void) {\n *     AssertEq(1 + 1, 2);\n *     AssertStrEq(\"hello\", \"hello\");\n *     AssertNull(NULL);\n *     return 42;\n * }\n * @endcode\n *\n * Each assertion macro expands to a call to an FFI-callable @c __builtin_assert_*\n * function.  On failure, the builtin prints the source location and expression,\n * then terminates with a failure exit code.\n */\n\n#pragma once\n\n// ============================================================================\n// Underlying FFI-callable assertion functions\n// ============================================================================\n\n/*!\n * @function __builtin_assert\n * @abstract Assert that a condition is true.\n * @param cond The boolean condition (must be non-zero to pass).\n * @param expr Stringified expression for diagnostic output.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c Assert and @c AssertTrue.\n */\nvoid __builtin_assert(int cond, const char *expr, const char *file, int line);\n\n/*!\n * @function __builtin_assert_false\n * @abstract Assert that a condition is false.\n * @param cond The boolean condition (must be zero to pass).\n * @param expr Stringified expression for diagnostic output.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertFalse.\n */\nvoid __builtin_assert_false(int cond, const char *expr, const char *file, int line);\n\n/*!\n * @function __builtin_assert_fail\n * @abstract Unconditionally fail a test.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertFail.\n */\nvoid __builtin_assert_fail(const char *file, int line);\n\n/*!\n * @function __builtin_assert_fail_msg\n * @abstract Unconditionally fail a test with a custom message.\n * @param msg Custom failure message.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertFailMsg.\n */\nvoid __builtin_assert_fail_msg(const char *msg, const char *file, int line);\n\n/*!\n * @function __builtin_assert_eq\n * @abstract Assert that two integers are equal.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n * @param as Stringified left expression.\n * @param bs Stringified right expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertEq.\n */\nvoid __builtin_assert_eq(long long a, long long b, const char *as, const char *bs,\n                     const char *file, int line);\n\n/*!\n * @function __builtin_assert_neq\n * @abstract Assert that two integers are not equal.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n * @param as Stringified left expression.\n * @param bs Stringified right expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertNeq.\n */\nvoid __builtin_assert_neq(long long a, long long b, const char *as, const char *bs,\n                      const char *file, int line);\n\n/*!\n * @function __builtin_assert_gt\n * @abstract Assert that one integer is greater than another.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n * @param as Stringified left expression.\n * @param bs Stringified right expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertGt.\n */\nvoid __builtin_assert_gt(long long a, long long b, const char *as, const char *bs,\n                     const char *file, int line);\n\n/*!\n * @function __builtin_assert_lt\n * @abstract Assert that one integer is less than another.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n * @param as Stringified left expression.\n * @param bs Stringified right expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertLt.\n */\nvoid __builtin_assert_lt(long long a, long long b, const char *as, const char *bs,\n                     const char *file, int line);\n\n/*!\n * @function __builtin_assert_ge\n * @abstract Assert that one integer is greater than or equal to another.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n * @param as Stringified left expression.\n * @param bs Stringified right expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertGe.\n */\nvoid __builtin_assert_ge(long long a, long long b, const char *as, const char *bs,\n                     const char *file, int line);\n\n/*!\n * @function __builtin_assert_le\n * @abstract Assert that one integer is less than or equal to another.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n * @param as Stringified left expression.\n * @param bs Stringified right expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertLe.\n */\nvoid __builtin_assert_le(long long a, long long b, const char *as, const char *bs,\n                     const char *file, int line);\n\n/*!\n * @function __builtin_assert_within\n * @abstract Assert that an integer is within a delta of an expected value.\n * @param delta Maximum allowed absolute difference.\n * @param expected Expected value.\n * @param actual Actual value.\n * @param ds Stringified delta expression.\n * @param es Stringified expected expression.\n * @param as Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertWithin.  Passes if\n *             |actual - expected| <= delta.\n */\nvoid __builtin_assert_within(long long delta, long long expected, long long actual,\n                         const char *ds, const char *es, const char *as,\n                         const char *file, int line);\n\n/*!\n * @function __builtin_assert_null\n * @abstract Assert that a pointer is NULL.\n * @param p The pointer to check.\n * @param ps Stringified pointer expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertNull.\n */\nvoid __builtin_assert_null(const void *p, const char *ps,\n                       const char *file, int line);\n\n/*!\n * @function __builtin_assert_not_null\n * @abstract Assert that a pointer is not NULL.\n * @param p The pointer to check.\n * @param ps Stringified pointer expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertNotNull.\n */\nvoid __builtin_assert_not_null(const void *p, const char *ps,\n                           const char *file, int line);\n\n/*!\n * @function __builtin_assert_streq\n * @abstract Assert that two C strings are equal (full strcmp).\n * @param a Expected string.\n * @param b Actual string.\n * @param as Stringified expected expression.\n * @param bs Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertStrEq.  Uses strcmp for comparison.\n */\nvoid __builtin_assert_streq(const char *a, const char *b,\n                        const char *as, const char *bs,\n                        const char *file, int line);\n\n/*!\n * @function __builtin_assert_streq_len\n * @abstract Assert that two C strings are equal up to a given length.\n * @param a Expected string.\n * @param b Actual string.\n * @param len Maximum number of characters to compare.\n * @param as Stringified expected expression.\n * @param bs Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertStrEqLen.  Uses strncmp for comparison.\n */\nvoid __builtin_assert_streq_len(const char *a, const char *b, long long len,\n                            const char *as, const char *bs,\n                            const char *file, int line);\n\n/*!\n * @function __builtin_assert_mem_eq\n * @abstract Assert that two memory regions are byte-identical.\n * @param expected Pointer to expected data.\n * @param actual Pointer to actual data.\n * @param len Number of bytes to compare.\n * @param es Stringified expected expression.\n * @param as Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertMemEq.  Uses memcmp for comparison.\n */\nvoid __builtin_assert_mem_eq(const void *expected, const void *actual, long long len,\n                         const char *es, const char *as,\n                         const char *file, int line);\n\n/*!\n * @function __builtin_assert_float_within\n * @abstract Assert that a float is within a delta of an expected value.\n * @param delta Maximum allowed absolute difference.\n * @param expected Expected value.\n * @param actual Actual value.\n * @param ds Stringified delta expression.\n * @param es Stringified expected expression.\n * @param as Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertFloatWithin and @c AssertFloatEq.\n *             Passes if |actual - expected| <= delta.\n */\nvoid __builtin_assert_float_within(double delta, double expected, double actual,\n                               const char *ds, const char *es, const char *as,\n                               const char *file, int line);\n\n/*!\n * @function __builtin_assert_double_within\n * @abstract Assert that a double is within a delta of an expected value.\n * @param delta Maximum allowed absolute difference.\n * @param expected Expected value.\n * @param actual Actual value.\n * @param ds Stringified delta expression.\n * @param es Stringified expected expression.\n * @param as Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertDoubleWithin and @c AssertDoubleEq.\n *             Passes if |actual - expected| <= delta.\n */\nvoid __builtin_assert_double_within(double delta, double expected, double actual,\n                                const char *ds, const char *es, const char *as,\n                                const char *file, int line);\n\n/*!\n * @function __builtin_assert_bits\n * @abstract Assert that specific bits match between expected and actual values.\n * @param mask Bit mask to apply.\n * @param expected Expected masked value.\n * @param actual Actual value to mask and compare.\n * @param ms Stringified mask expression.\n * @param es Stringified expected expression.\n * @param as Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertBits.  Passes if\n *             (actual & mask) == (expected & mask).\n */\nvoid __builtin_assert_bits(long long mask, long long expected, long long actual,\n                       const char *ms, const char *es, const char *as,\n                       const char *file, int line);\n\n/*!\n * @function __builtin_assert_bit_high\n * @abstract Assert that a specific bit is set (high/1).\n * @param bit Zero-based bit index.\n * @param actual Value to inspect.\n * @param bs Stringified bit index expression.\n * @param as Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertBitHigh.  Passes if (actual >> bit) & 1.\n */\nvoid __builtin_assert_bit_high(int bit, long long actual,\n                           const char *bs, const char *as,\n                           const char *file, int line);\n\n/*!\n * @function __builtin_assert_bit_low\n * @abstract Assert that a specific bit is clear (low/0).\n * @param bit Zero-based bit index.\n * @param actual Value to inspect.\n * @param bs Stringified bit index expression.\n * @param as Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertBitLow.  Passes if !((actual >> bit) & 1).\n */\nvoid __builtin_assert_bit_low(int bit, long long actual,\n                          const char *bs, const char *as,\n                          const char *file, int line);\n\n/*!\n * @function __builtin_assert_eq_array\n * @abstract Assert that two arrays are element-by-element equal.\n * @param expected Pointer to expected array.\n * @param actual Pointer to actual array.\n * @param elem_size Size of each element in bytes.\n * @param count Number of elements to compare.\n * @param es Stringified expected expression.\n * @param as Stringified actual expression.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertArrayEq.  Uses memcmp internally.\n */\nvoid __builtin_assert_eq_array(const void *expected, const void *actual,\n                           long long elem_size, long long count,\n                           const char *es, const char *as,\n                           const char *file, int line);\n\n// ============================================================================\n// Message-appending variants\n// ============================================================================\n\n/*!\n * @function __builtin_assert_msg\n * @abstract Assert a condition is true with a custom message.\n * @param cond The boolean condition (must be non-zero to pass).\n * @param expr Stringified expression for diagnostic output.\n * @param msg Custom failure message.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertMsg and @c AssertTrueMsg.\n */\nvoid __builtin_assert_msg(int cond, const char *expr, const char *msg,\n                      const char *file, int line);\n\n/*!\n * @function __builtin_assert_eq_msg\n * @abstract Assert two integers are equal with a custom message.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n * @param as Stringified left expression.\n * @param bs Stringified right expression.\n * @param msg Custom failure message.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertEqMsg.\n */\nvoid __builtin_assert_eq_msg(long long a, long long b,\n                         const char *as, const char *bs, const char *msg,\n                         const char *file, int line);\n\n/*!\n * @function __builtin_assert_streq_msg\n * @abstract Assert two C strings are equal with a custom message.\n * @param a Expected string.\n * @param b Actual string.\n * @param as Stringified expected expression.\n * @param bs Stringified actual expression.\n * @param msg Custom failure message.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertStrEqMsg.\n */\nvoid __builtin_assert_streq_msg(const char *a, const char *b,\n                            const char *as, const char *bs, const char *msg,\n                            const char *file, int line);\n\n/*!\n * @function __builtin_assert_null_msg\n * @abstract Assert a pointer is NULL with a custom message.\n * @param p The pointer to check.\n * @param ps Stringified pointer expression.\n * @param msg Custom failure message.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertNullMsg.\n */\nvoid __builtin_assert_null_msg(const void *p, const char *ps, const char *msg,\n                           const char *file, int line);\n\n/*!\n * @function __builtin_assert_not_null_msg\n * @abstract Assert a pointer is not NULL with a custom message.\n * @param p The pointer to check.\n * @param ps Stringified pointer expression.\n * @param msg Custom failure message.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertNotNullMsg.\n */\nvoid __builtin_assert_not_null_msg(const void *p, const char *ps, const char *msg,\n                               const char *file, int line);\n\n/*!\n * @function __builtin_assert_bits_msg\n * @abstract Assert specific bits match with a custom message.\n * @param mask Bit mask to apply.\n * @param expected Expected masked value.\n * @param actual Actual value to mask and compare.\n * @param ms Stringified mask expression.\n * @param es Stringified expected expression.\n * @param as Stringified actual expression.\n * @param msg Custom failure message.\n * @param file Source file name.\n * @param line Source line number.\n * @discussion Backend for @c AssertBitsMsg.  Passes if\n *             (actual & mask) == (expected & mask).\n */\nvoid __builtin_assert_bits_msg(long long mask, long long expected, long long actual,\n                           const char *ms, const char *es, const char *as,\n                           const char *msg, const char *file, int line);\n\n// ============================================================================\n// Basic Validity Assertions\n// ============================================================================\n\n/*!\n * @define Assert\n * @abstract Assert that a condition is true.\n * @param cond The condition to test.\n * @discussion Expands to __builtin_assert with stringified expression,\n *             source file, and line.  Equivalent to @c AssertTrue.\n */\n#define Assert(cond) \\\n    __builtin_assert(!!(cond), #cond, __FILE__, __LINE__)\n\n/*!\n * @define AssertTrue\n * @abstract Assert that a condition is true (alias for Assert).\n * @param cond The condition to test.\n */\n#define AssertTrue(cond) \\\n    Assert(cond)\n\n/*!\n * @define AssertFalse\n * @abstract Assert that a condition is false.\n * @param cond The condition to test (must evaluate to zero).\n */\n#define AssertFalse(cond) \\\n    __builtin_assert_false(!!(cond), #cond, __FILE__, __LINE__)\n\n/*!\n * @define AssertFail\n * @abstract Unconditionally fail the current test.\n */\n#define AssertFail() \\\n    __builtin_assert_fail(__FILE__, __LINE__)\n\n/*!\n * @define AssertFailMsg\n * @abstract Unconditionally fail the current test with a custom message.\n * @param msg Custom failure message.\n */\n#define AssertFailMsg(msg) \\\n    __builtin_assert_fail_msg(msg, __FILE__, __LINE__)\n\n// ============================================================================\n// Numerical Assertions: Integers\n// ============================================================================\n\n/*!\n * @define AssertEq\n * @abstract Assert two integers are equal.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n */\n#define AssertEq(a, b) \\\n    __builtin_assert_eq((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n\n/*!\n * @define AssertNeq\n * @abstract Assert two integers are not equal.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n */\n#define AssertNeq(a, b) \\\n    __builtin_assert_neq((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n\n/*!\n * @define AssertGt\n * @abstract Assert one integer is greater than another.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n */\n#define AssertGt(a, b) \\\n    __builtin_assert_gt((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n\n/*!\n * @define AssertLt\n * @abstract Assert one integer is less than another.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n */\n#define AssertLt(a, b) \\\n    __builtin_assert_lt((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n\n/*!\n * @define AssertGe\n * @abstract Assert one integer is greater than or equal to another.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n */\n#define AssertGe(a, b) \\\n    __builtin_assert_ge((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n\n/*!\n * @define AssertLe\n * @abstract Assert one integer is less than or equal to another.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n */\n#define AssertLe(a, b) \\\n    __builtin_assert_le((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n\n/*!\n * @define AssertWithin\n * @abstract Assert an integer is within a delta of an expected value.\n * @param delta Maximum allowed absolute difference.\n * @param expected Expected value.\n * @param actual Actual value.\n * @discussion Passes if |actual - expected| <= delta.\n */\n#define AssertWithin(delta, expected, actual) \\\n    __builtin_assert_within((long long)(delta), (long long)(expected), (long long)(actual), \\\n                        #delta, #expected, #actual, __FILE__, __LINE__)\n\n// ============================================================================\n// Numerical Assertions: Bitwise\n// ============================================================================\n\n/*!\n * @define AssertBits\n * @abstract Assert that specific bits match between expected and actual values.\n * @param mask Bit mask to apply.\n * @param expected Expected masked value.\n * @param actual Actual value to mask and compare.\n * @discussion Passes if (actual & mask) == (expected & mask).\n */\n#define AssertBits(mask, expected, actual) \\\n    __builtin_assert_bits((long long)(mask), (long long)(expected), (long long)(actual), \\\n                      #mask, #expected, #actual, __FILE__, __LINE__)\n\n/*!\n * @define AssertBitHigh\n * @abstract Assert that a specific bit is set (high/1).\n * @param bit Zero-based bit index.\n * @param actual Value to inspect.\n * @discussion Passes if (actual >> bit) & 1.\n */\n#define AssertBitHigh(bit, actual) \\\n    __builtin_assert_bit_high((int)(bit), (long long)(actual), \\\n                          #bit, #actual, __FILE__, __LINE__)\n\n/*!\n * @define AssertBitLow\n * @abstract Assert that a specific bit is clear (low/0).\n * @param bit Zero-based bit index.\n * @param actual Value to inspect.\n * @discussion Passes if !((actual >> bit) & 1).\n */\n#define AssertBitLow(bit, actual) \\\n    __builtin_assert_bit_low((int)(bit), (long long)(actual), \\\n                         #bit, #actual, __FILE__, __LINE__)\n\n// ============================================================================\n// Numerical Assertions: Floats / Doubles\n// ============================================================================\n\n/*!\n * @define AssertFloatWithin\n * @abstract Assert a float is within a delta of an expected value.\n * @param delta Maximum allowed absolute difference.\n * @param expected Expected value.\n * @param actual Actual value.\n */\n#define AssertFloatWithin(delta, expected, actual) \\\n    __builtin_assert_float_within((double)(delta), (double)(expected), (double)(actual), \\\n                              #delta, #expected, #actual, __FILE__, __LINE__)\n\n/*!\n * @define AssertDoubleWithin\n * @abstract Assert a double is within a delta of an expected value.\n * @param delta Maximum allowed absolute difference.\n * @param expected Expected value.\n * @param actual Actual value.\n */\n#define AssertDoubleWithin(delta, expected, actual) \\\n    __builtin_assert_double_within((double)(delta), (double)(expected), (double)(actual), \\\n                               #delta, #expected, #actual, __FILE__, __LINE__)\n\n/*!\n * @define AssertFloatEq\n * @abstract Assert two floats are approximately equal (default epsilon 1e-6).\n * @param expected Expected value.\n * @param actual Actual value.\n * @discussion Uses a default delta of 1e-6.\n */\n#define AssertFloatEq(expected, actual) \\\n    __builtin_assert_float_within(1e-6, (double)(expected), (double)(actual), \\\n                              #expected, #expected, #actual, __FILE__, __LINE__)\n\n/*!\n * @define AssertDoubleEq\n * @abstract Assert two doubles are approximately equal (default epsilon 1e-15).\n * @param expected Expected value.\n * @param actual Actual value.\n * @discussion Uses a default delta of 1e-15.\n */\n#define AssertDoubleEq(expected, actual) \\\n    __builtin_assert_double_within(1e-15, (double)(expected), (double)(actual), \\\n                               #expected, #expected, #actual, __FILE__, __LINE__)\n\n// ============================================================================\n// Pointer Assertions\n// ============================================================================\n\n/*!\n * @define AssertNull\n * @abstract Assert a pointer is NULL.\n * @param p The pointer to check.\n */\n#define AssertNull(p) \\\n    __builtin_assert_null((const void *)(p), #p, __FILE__, __LINE__)\n\n/*!\n * @define AssertNotNull\n * @abstract Assert a pointer is not NULL.\n * @param p The pointer to check.\n */\n#define AssertNotNull(p) \\\n    __builtin_assert_not_null((const void *)(p), #p, __FILE__, __LINE__)\n\n// ============================================================================\n// String Assertions\n// ============================================================================\n\n/*!\n * @define AssertStrEq\n * @abstract Assert two C strings are equal.\n * @param a Expected string.\n * @param b Actual string.\n */\n#define AssertStrEq(a, b) \\\n    __builtin_assert_streq((a), (b), #a, #b, __FILE__, __LINE__)\n\n/*!\n * @define AssertStrEqLen\n * @abstract Assert two C strings are equal up to a given length.\n * @param a Expected string.\n * @param b Actual string.\n * @param len Maximum number of characters to compare.\n */\n#define AssertStrEqLen(a, b, len) \\\n    __builtin_assert_streq_len((a), (b), (long long)(len), #a, #b, __FILE__, __LINE__)\n\n// ============================================================================\n// Memory Assertions\n// ============================================================================\n\n/*!\n * @define AssertMemEq\n * @abstract Assert two memory regions are byte-identical.\n * @param expected Pointer to expected data.\n * @param actual Pointer to actual data.\n * @param len Number of bytes to compare.\n */\n#define AssertMemEq(expected, actual, len) \\\n    __builtin_assert_mem_eq((const void *)(expected), (const void *)(actual), \\\n                        (long long)(len), #expected, #actual, __FILE__, __LINE__)\n\n// ============================================================================\n// Array Assertions\n// ============================================================================\n\n/*!\n * @define AssertArrayEq\n * @abstract Assert two arrays are element-by-element equal.\n * @param expected Pointer to expected array.\n * @param actual Pointer to actual array.\n * @param count Number of elements (element size is inferred).\n * @discussion Uses sizeof((expected)[0]) to infer element size.\n */\n#define AssertArrayEq(expected, actual, count) \\\n    __builtin_assert_eq_array((const void *)(expected), (const void *)(actual), \\\n                          (long long)sizeof((expected)[0]), (long long)(count), \\\n                          #expected, #actual, __FILE__, __LINE__)\n\n/*!\n * @define AssertEachEq\n * @abstract Assert each element of an array equals a scalar expected value.\n * @param expected Scalar expected value.\n * @param actual Array expression.\n * @param count Number of elements.\n * @discussion Iterates over the array and compares each element individually.\n *             On failure, reports the failing index as \"[i]\".\n */\n#define AssertEachEq(expected, actual, count) \\\n    do { \\\n        long long _cccc_i_; \\\n        for (_cccc_i_ = 0; _cccc_i_ < (long long)(count); _cccc_i_++) \\\n            __builtin_assert_eq((long long)((expected)), \\\n                           (long long)(((const typeof((actual)[0])*)(actual))[_cccc_i_]), \\\n                           #expected, #actual \"[i]\", \\\n                           __FILE__, __LINE__); \\\n    } while (0)\n\n// ============================================================================\n// Message-appending variants (_msg suffix)\n// ============================================================================\n\n/*!\n * @define AssertMsg\n * @abstract Assert a condition is true with a custom message.\n * @param cond The condition to test.\n * @param msg Custom failure message.\n */\n#define AssertMsg(cond, msg) \\\n    __builtin_assert_msg(!!(cond), #cond, msg, __FILE__, __LINE__)\n\n/*!\n * @define AssertTrueMsg\n * @abstract Assert a condition is true with a custom message (alias for AssertMsg).\n * @param cond The condition to test.\n * @param msg Custom failure message.\n */\n#define AssertTrueMsg(cond, msg) \\\n    AssertMsg(cond, msg)\n\n/*!\n * @define AssertFalseMsg\n * @abstract Assert a condition is false with a custom message.\n * @param cond The condition to test.\n * @param msg Custom failure message.\n */\n#define AssertFalseMsg(cond, msg) \\\n    __builtin_assert_msg(!(cond), #cond, msg, __FILE__, __LINE__)\n\n/*!\n * @define AssertEqMsg\n * @abstract Assert two integers are equal with a custom message.\n * @param a Left-hand operand.\n * @param b Right-hand operand.\n * @param msg Custom failure message.\n */\n#define AssertEqMsg(a, b, msg) \\\n    __builtin_assert_eq_msg((long long)(a), (long long)(b), #a, #b, msg, \\\n                        __FILE__, __LINE__)\n\n/*!\n * @define AssertStrEqMsg\n * @abstract Assert two C strings are equal with a custom message.\n * @param a Expected string.\n * @param b Actual string.\n * @param msg Custom failure message.\n */\n#define AssertStrEqMsg(a, b, msg) \\\n    __builtin_assert_streq_msg((a), (b), #a, #b, msg, __FILE__, __LINE__)\n\n/*!\n * @define AssertNullMsg\n * @abstract Assert a pointer is NULL with a custom message.\n * @param p The pointer to check.\n * @param msg Custom failure message.\n */\n#define AssertNullMsg(p, msg) \\\n    __builtin_assert_null_msg((const void *)(p), #p, msg, __FILE__, __LINE__)\n\n/*!\n * @define AssertNotNullMsg\n * @abstract Assert a pointer is not NULL with a custom message.\n * @param p The pointer to check.\n * @param msg Custom failure message.\n */\n#define AssertNotNullMsg(p, msg) \\\n    __builtin_assert_not_null_msg((const void *)(p), #p, msg, __FILE__, __LINE__)\n\n/*!\n * @define AssertBitsMsg\n * @abstract Assert specific bits match with a custom message.\n * @param mask Bit mask to apply.\n * @param expected Expected masked value.\n * @param actual Actual value to mask and compare.\n * @param msg Custom failure message.\n */\n#define AssertBitsMsg(mask, expected, actual, msg) \\\n    __builtin_assert_bits_msg((long long)(mask), (long long)(expected), (long long)(actual), \\\n                          #mask, #expected, #actual, msg, __FILE__, __LINE__)\n";
static char __builtin_tgmath_h[1690] = "/* tgmath.h - type-generic math macros for CCCC */\n\n#ifndef __TGMATH_H\n#define __TGMATH_H\n\n#include \"math.h\"\n#include \"complex.h\"\n\n#define __cccc_tg_unary(x, fd, ff, fl) _Generic((x), \\\n    long double: fl, \\\n    float: ff, \\\n    default: fd)(x)\n\n#define __cccc_tg_binary(x, y, fd, ff, fl) _Generic(((x) + (y)), \\\n    long double: fl, \\\n    float: ff, \\\n    default: fd)(x, y)\n\n#define __cccc_tg_real_or_complex_abs(x) _Generic((x), \\\n    long double _Complex: cabsl(x), \\\n    double _Complex: cabs(x), \\\n    float _Complex: cabsf(x), \\\n    long double: fabsl(x), \\\n    float: fabsf(x), \\\n    default: fabs(x))\n\n#define acos(x) __cccc_tg_unary((x), acos, acosf, acosl)\n#define asin(x) __cccc_tg_unary((x), asin, asinf, asinl)\n#define atan(x) __cccc_tg_unary((x), atan, atanf, atanl)\n#define cos(x) __cccc_tg_unary((x), cos, cosf, cosl)\n#define sin(x) __cccc_tg_unary((x), sin, sinf, sinl)\n#define tan(x) __cccc_tg_unary((x), tan, tanf, tanl)\n#define exp(x) __cccc_tg_unary((x), exp, expf, expl)\n#define log(x) __cccc_tg_unary((x), log, logf, logl)\n#define sqrt(x) __cccc_tg_unary((x), sqrt, sqrtf, sqrtl)\n#define fabs(x) __cccc_tg_real_or_complex_abs((x))\n#define floor(x) __cccc_tg_unary((x), floor, floorf, floorl)\n#define ceil(x) __cccc_tg_unary((x), ceil, ceilf, ceill)\n#define trunc(x) __cccc_tg_unary((x), trunc, truncf, truncl)\n#define round(x) __cccc_tg_unary((x), round, roundf, roundl)\n#define pow(x, y) __cccc_tg_binary((x), (y), pow, powf, powl)\n#define fmod(x, y) __cccc_tg_binary((x), (y), fmod, fmodf, fmodl)\n#define atan2(x, y) __cccc_tg_binary((x), (y), atan2, atan2f, atan2l)\n#define hypot(x, y) __cccc_tg_binary((x), (y), hypot, hypotf, hypotl)\n\n#endif /* __TGMATH_H */\n";
static char __builtin_threads_h[2523] = "#ifndef __THREADS_H\n#define __THREADS_H\n\n#ifdef _WIN32\n#error \"<threads.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"pthread.h\"\n#include \"time.h\"\n#include \"errno.h\"\n\n/* C11 thread type backed by the existing pthread VM implementation */\ntypedef pthread_t thrd_t;\n\n/* Thread-specific storage key */\ntypedef pthread_key_t tss_t;\ntypedef void (*tss_dtor_t)(void *);\n\n/* Mutex: store the C11 type flag so mtx_init can configure appropriately.\n   Layout mirrors CCCCUserMutex (void *__handle, long __state) plus an int\n   type tag; the host mutex is lazily allocated on first lock. */\ntypedef struct {\n    void *__handle;\n    long  __state;\n    int   __type;\n} mtx_t;\n\n/* Condition variable backed by pthread cond */\ntypedef struct {\n    void *__handle;\n    long  __state;\n} cnd_t;\n\n/* Thread start function returning int (differs from pthread's void*) */\ntypedef int (*thrd_start_t)(void *);\n\n/* Mutex type flags */\nenum {\n    mtx_plain     = 0,\n    mtx_recursive = 1,\n    mtx_timed     = 2,\n};\n\n/* Return codes */\nenum {\n    thrd_success  = 0,\n    thrd_error    = 1,\n    thrd_timedout = ETIMEDOUT,\n    thrd_busy     = EBUSY,\n    thrd_nomem    = ENOMEM,\n};\n\n/* call_once: under the GIL, bytecode execution is serialised so a simple\n   flag check + call is atomic from the VM's perspective. */\ntypedef _Atomic int once_flag;\n#define ONCE_FLAG_INIT 0\n\n#define call_once(flag, func) \\\n    do { if (!(*(flag))) { *(flag) = 1; (func)(); } } while (0)\n\n/* ---- Thread lifecycle ---- */\nint    thrd_create(thrd_t *thr, thrd_start_t func, void *arg);\nint    thrd_join(thrd_t thr, int *res);\nvoid   thrd_exit(int res);\nint    thrd_detach(thrd_t thr);\nvoid   thrd_yield(void);\nint    thrd_sleep(const struct timespec *duration, struct timespec *remaining);\nthrd_t thrd_current(void);\nint    thrd_equal(thrd_t a, thrd_t b);\n\n/* ---- Mutex ---- */\nint  mtx_init(mtx_t *mtx, int type);\nint  mtx_lock(mtx_t *mtx);\nint  mtx_trylock(mtx_t *mtx);\nint  mtx_timedlock(mtx_t *mtx, const struct timespec *ts);\nint  mtx_unlock(mtx_t *mtx);\nvoid mtx_destroy(mtx_t *mtx);\n\n/* ---- Condition variable ---- */\nint  cnd_init(cnd_t *cond);\nint  cnd_wait(cnd_t *cond, mtx_t *mtx);\nint  cnd_signal(cnd_t *cond);\nint  cnd_broadcast(cnd_t *cond);\nint  cnd_timedwait(cnd_t *cond, mtx_t *mtx, const struct timespec *ts);\nvoid cnd_destroy(cnd_t *cond);\n\n/* ---- Thread-specific storage ---- */\nint   tss_create(tss_t *key, tss_dtor_t dtor);\nvoid *tss_get(tss_t key);\nint   tss_set(tss_t key, void *val);\nvoid  tss_delete(tss_t key);\n\n#endif\n";
static char __builtin_time_h[1248] = "/* time.h - time functions for CCCC C compiler */\n\n#ifndef __TIME_H\n#define __TIME_H\n\n#include \"stddef.h\"\n\ntypedef long clock_t;\ntypedef long time_t;\n\n#define CLOCKS_PER_SEC 1000000\n\nstruct timespec {\n    time_t tv_sec;\n    long tv_nsec;\n};\n\n#define TIME_UTC 1\n\nstruct tm {\n    int tm_sec;\n    int tm_min;\n    int tm_hour;\n    int tm_mday;\n    int tm_mon;\n    int tm_year;\n    int tm_wday;\n    int tm_yday;\n    int tm_isdst;\n    long tm_gmtoff;\n    char *tm_zone;\n};\n\nextern clock_t clock(void);\nextern double difftime(time_t time1, time_t time0);\nextern time_t mktime(struct tm *timeptr);\nextern time_t timegm(struct tm *timeptr);\nextern time_t time(time_t *t);\nextern int timespec_get(struct timespec *ts, int base);\n// extern int timespec_getres(struct timespec *ts, int base);\nextern char *asctime(const struct tm *tm); // deprecated\nextern char *ctime(const time_t *timer); // deprecated\nextern struct tm *gmtime(const time_t *timer);\nextern struct tm *gmtime_r(const time_t *timer, struct tm *result);\nextern struct tm *localtime(const time_t *timer);\nextern struct tm *localtime_r(const time_t *timer, struct tm *result);\nextern size_t strftime(char *s, size_t maxsize, const char *format, const struct tm *timeptr);\n\n#endif /* __TIME_H */\n";
static char __builtin_uchar_h[703] = "/* uchar.h - Unicode character conversion declarations for CCCC */\n\n#ifndef __UCHAR_H\n#define __UCHAR_H\n\n#include \"stddef.h\"\n#include \"wchar.h\"\n\ntypedef unsigned char  char8_t;   // C23 \302\2477.28\ntypedef unsigned short char16_t;\ntypedef unsigned int char32_t;\n\nextern size_t mbrtoc8(char8_t *pc8, const char *s, size_t n, mbstate_t *ps);\nextern size_t c8rtomb(char *s, char8_t c8, mbstate_t *ps);\nextern size_t mbrtoc16(char16_t *pc16, const char *s, size_t n, mbstate_t *ps);\nextern size_t c16rtomb(char *s, char16_t c16, mbstate_t *ps);\nextern size_t mbrtoc32(char32_t *pc32, const char *s, size_t n, mbstate_t *ps);\nextern size_t c32rtomb(char *s, char32_t c32, mbstate_t *ps);\n\n#endif /* __UCHAR_H */\n";
static char __builtin_unistd_h[1935] = "/* unistd.h - core POSIX declarations for CCCC */\n\n#ifndef __UNISTD_H\n#define __UNISTD_H\n\n#ifdef _WIN32\n#error \"<unistd.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"stddef.h\"\n#include \"sys/types.h\"\n\n#ifndef _SSIZE_T\ntypedef long ssize_t;\n#define _SSIZE_T\n#endif\n\n#ifndef NULL\n#define NULL ((void*)0)\n#endif\n\n#define STDIN_FILENO 0\n#define STDOUT_FILENO 1\n#define STDERR_FILENO 2\n\n#ifndef SEEK_SET\n#define SEEK_SET 0\n#define SEEK_CUR 1\n#define SEEK_END 2\n#endif\n\n#define F_OK 0\n#define X_OK 1\n#define W_OK 2\n#define R_OK 4\n\nextern ssize_t read(int fd, void *buf, size_t count);\nextern ssize_t write(int fd, const void *buf, size_t count);\nextern int close(int fd);\nextern off_t lseek(int fd, off_t offset, int whence);\nextern int access(const char *path, int amode);\nextern int unlink(const char *path);\nextern int rmdir(const char *path);\nextern int chdir(const char *path);\nextern char *getcwd(char *buf, size_t size);\nextern pid_t getpid(void);\nextern pid_t getppid(void);\nextern unsigned int sleep(unsigned int seconds);\nextern int usleep(unsigned int useconds);\nextern int pipe(int fd[2]);\nextern void _exit(int status);\nextern pid_t fork(void);\nextern int execv(const char *path, char *const argv[]);\nextern int execve(const char *path, char *const argv[], char *const envp[]);\nextern int execl(const char *path, const char *arg, ...);\nextern int execlp(const char *file, const char *arg, ...);\nextern int execle(const char *path, const char *arg, ...);\nextern int execvp(const char *file, char *const argv[]);\nextern int isatty(int fd);\nextern char *ttyname(int fd);\nextern int dup(int fd);\nextern int dup2(int oldfd, int newfd);\nextern int fsync(int fd);\nextern int ftruncate(int fd, off_t length);\nextern int truncate(const char *path, off_t length);\nextern long sysconf(int name);\nextern int mkstemp(char *tmpl);\nextern char *mkdtemp(char *tmpl);\n\n#define _SC_NPROCESSORS_ONLN 58\n\n#endif /* __UNISTD_H */\n";
static char __builtin_utime_h[332] = "/* utime.h - file access and modification times for CCCC */\n\n#ifndef __UTIME_H\n#define __UTIME_H\n\n#ifdef _WIN32\n#error \"<utime.h> is only available on POSIX targets in CCCC\"\n#endif\n\nstruct utimbuf {\n    long actime;\n    long modtime;\n};\n\nextern int utime(const char *filename, const struct utimbuf *times);\n\n#endif /* __UTIME_H */\n";
